		_this.jixu.visible = false;
		_this.group.visible = false;
		_this.groupB.visible = false;
		_this.showB.visible = false;
		var btnNum = 3;
		for (var i = 1; i <= btnNum; i++) {
			_this.group['anniu_' + i].mouseChildren = false;
			_this['show' + i].visible = false;
		}
		_this.groupB.btn_1.mouseChildren = false;
		_this.groupB.btn_2.mouseChildren = false;
		_this.open.mouseChildren = false;
		_this.turn2.mouseChildren = false;
		var Array1 = ['未回答'];
		
		
		var win = window;
		while (win !== win.parent && win.VarQuestion_0002 === undefined) {
			win = win.parent;
		}
		var answerArr = {
			1: '急促',
			2: '减慢',
			3: '正常'
		}
		var answerArrB = {
			1: '缺氧状态',
			2: '呼吸正常'
		}
		
		var curNum = 0;
		var curNumB = 0;
		_this.addEventListener("click", function (e) {
			if (e.target.name) {
				if (e.target.name.indexOf("anniu_") >= 0) {
		
					curNum = Number(e.target.name.substring(6));
					//console.log(curNum)
					for (var i = 1; i <= btnNum; i++) {
						_this['show' + i].visible = false;
					}
					_this['show' + curNum].visible = true;
		
					_this.group.visible = false;
					playSound('click');
				} else if (e.target.name.indexOf("queding") >= 0) {
		
		
					_this.daan.visible = true;
					_this.jixu.visible = true;
					_this.showB.visible = true;
		
					if (curNum == 1 && curNumB == 1) {
						playSound('correct');
						_this.daan.gotoAndStop(0);
					} else {
						for (var i = 1; i <= btnNum; i++) {
							_this['show' + i].visible = false;
						}
						_this.show1.visible = true;
						_this.showB.gotoAndStop(0);
						_this.daan.gotoAndStop(1);
						playSound('error');
					}
					_this.open.visible = false;
					_this.turn2.visible = false;
					_this.group.visible = false;
					_this.tishi1.visible = false;
					_this.tishi2.visible = false;
		
					if (curNum == 0) {
						win.VarQuestion_0002.set(Array1.toString());
					} else {
						win.VarQuestion_0002.set(answerArr[curNum]+'、'+answerArrB[curNumB]);
					}
		
				} else if (e.target.name.indexOf("jixu") >= 0) {
					playSound('click');
					window.parent.trivNextPage();
				} else if (e.target.name.indexOf("open") >= 0) {
					playSound('click');
					_this.group.visible = true;
					_this.tishi1.visible = false;
				} else if (e.target.name.indexOf("turn2") >= 0) {
					playSound('click');
					_this.groupB.visible = true;
					_this.tishi2.visible = false;
				} else if (e.target.name.indexOf("btn_") >= 0) {
					curNumB = Number(e.target.name.substring(4));
					//console.log(curNum)
					_this.showB.visible = true;
					_this.showB.gotoAndStop(curNumB - 1);
					
					_this.groupB.visible = false;
					playSound('click');
				}
			}
		});
